<script setup>
import {computed,nextTick,ref,watch} from 'vue'
import {useStation} from './useStation.js'
import {count,mean,percent,tierLabel,dateLabel,sceneName,signed} from './dataModel.js'
import Icon from './components/Icon.vue'
import MetricStrip from './components/MetricStrip.vue'
import TrendChart from './components/TrendChart.vue'
import ScopeMatrix from './components/ScopeMatrix.vue'
import FanView from './components/FanView.vue'
import RecordTable from './components/RecordTable.vue'
import PlayerView from './components/PlayerView.vue'
import DuplicateView from './components/DuplicateView.vue'
import AnalysisView from './components/AnalysisView.vue'
import RecordDetail from './components/RecordDetail.vue'
const layouts=[
  {key:'overview',name:'总览中枢',tag:'快速掌握整体',desc:'纵向导航、指标首屏、趋势与场次并置。适合默认入口，先看全貌，再进入玩家或牌谱。'},
  {key:'workbench',name:'研究工作台',tag:'密集对比与检索',desc:'固定筛选区、场次比较矩阵、密集牌谱表格。适合经常查数据的人，减少上下切换。'},
  {key:'report',name:'数据阅览',tag:'有顺序地读数据',desc:'大数字开篇、章节式叙述、图文并排。适合公开展示、分享阶段观察，阅读节奏更明确。'},
  {key:'explorer',name:'对局探索器',tag:'从范围找到对局',desc:'左侧选范围、中间探索日历与牌谱、右侧保留上下文。适合从某个时间或场次继续查找。'},
  {key:'embedded',name:'内嵌数据站',tag:'游戏内随时查阅',desc:'窗口内顶部标签、可收起的范围筛选、紧凑的图表与牌谱。内容独立滚动，可直接作为 WebView / iframe 的内容页。'},
]
const views=[
  {key:'overview',name:'平台总览',en:'PLATFORM OVERVIEW',icon:'grid',description:'从场次、趋势到对局，观察平台的每一次变化。'},
  {key:'players',name:'玩家档案',en:'PLAYER PROFILE',icon:'person',description:'查看个人的对局样本、顺位变化与攻守表现。'},
  {key:'records',name:'对局与精选',en:'RECORD ARCHIVE',icon:'record',description:'查询最近牌谱，从公开记录进入完整回放。'},
  {key:'fans',name:'番种观察',en:'HAND PATTERNS',icon:'fan',description:'用频次、矩阵和明细表，观察不同番种的出现情况。'},
  {key:'analysis',name:'深度分析',en:'RECORD ANALYSIS',icon:'chart',description:'查看资料覆盖，继续进入现有的完整牌谱分析。'},
  {key:'duplicate',name:'复式资料',en:'DUPLICATE LIBRARY',icon:'key',description:'查找已公开的同牌山资料和关联对局。'},
]
const query=new URLSearchParams(location.search)
const embedOnly=query.get('embed')==='1'
const filtersOpen=ref(false),windowExpanded=ref(false)
const mainContent=ref(null)
const layout=ref(embedOnly?'embedded':layouts.some(l=>l.key===query.get('layout'))?query.get('layout'):'overview')
const view=ref(views.some(v=>v.key===query.get('view'))?query.get('view'):'overview')
const previewState=ref('normal'),notes=ref(null),detail=ref(null),contextRecord=ref(null),selectedDay=ref(null),playerQuery=ref('')
const {source,rule,days,tier,eventId,loading,error,dataset,records,recordTotal,recordPage,recordLoading,recordError,classics,hierarchy,extrasError,definition,ruleName,rows,total,series,periodGames,fans,metrics,loadStats,loadRecords,refresh,selectTier,rules}=useStation()
const currentView=computed(()=>views.find(v=>v.key===view.value))
const currentLayout=computed(()=>layouts.find(v=>v.key===layout.value))
const fanSupported=computed(()=>dataset.value.supports_fan_stats!==false&&definition.value?.fan_stats!==false)
const visibleClassics=computed(()=>classics.value.filter(r=>r.rule===definition.value?.rule||r.rule===rule.value))
const displayState=computed(()=>previewState.value!=='normal'?previewState.value:(['overview','fans'].includes(view.value)&&loading.value?'loading':['overview','fans'].includes(view.value)&&error.value?'error':view.value==='overview'&&!dataset.value.totals.length?'empty':'normal'))
const unit=computed(()=>({fan:'番',fu:'符',tai:'台',base_points:'基本分',points:'点',multiplier:'倍'})[definition.value?.win_stat_unit]||'')
const peak=computed(()=>series.value.reduce((best,day)=>day.value>best.value?day:best,{date:'—',value:0}))
const scopeCaption=computed(()=>eventId.value?(dataset.value.events.find(e=>(e.event_id||e.id)===eventId.value)?.name||dataset.value.events.find(e=>(e.event_id||e.id)===eventId.value)?.event_name||'比赛 / 基地'):tierLabel(tier.value))
function chooseRecord(record){contextRecord.value=record;if(layout.value!=='explorer'||view.value!=='overview')detail.value=record}
function choosePlayer(value){detail.value=null;playerQuery.value=String(value);view.value='players'}
function navigate(value){view.value=value;previewState.value='normal'}
watch([layout,view,source,rule],()=>{const q=new URLSearchParams({layout:layout.value,view:view.value,source:source.value,rule:rule.value});if(embedOnly)q.set('embed','1');history.replaceState(null,'',location.pathname+'?'+q)})
watch([source,rule,tier,eventId],()=>{contextRecord.value=null;selectedDay.value=null;detail.value=null})
watch(view,async()=>{await nextTick();mainContent.value?.scrollTo({top:0})})
</script>
<template>
  <div class="design-preview" :class="{'preview-embedded':layout==='embedded','embed-only':embedOnly,'window-expanded':windowExpanded}">
    <div v-if="!embedOnly" class="review-bar"><span class="review-label">布局提案</span><div class="layout-switch" aria-label="选择布局方案"><button v-for="(item,i) in layouts" :key="item.key" :class="{active:layout===item.key}" :aria-pressed="layout===item.key" @click="layout=item.key"><span>0{{i+1}}</span>{{item.name}}</button></div><div class="review-options"><select v-model="source" aria-label="数据来源"><option value="live">本地接口数据</option><option value="demo">虚构示例数据</option></select><select v-model="previewState" aria-label="预览页面状态"><option value="normal">正常状态</option><option value="empty">空数据</option><option value="loading">加载中</option><option value="error">加载失败</option></select><button class="review-notes" @click="notes.showModal()">方案说明 <Icon name="info" :size="15"/></button></div></div>
    <div :class="['station','layout-'+layout]">
      <header v-if="layout==='embedded'" class="station-header embedded-header">
        <div class="embedded-title"><span class="embedded-symbol"><Icon name="chart" :size="21"/></span><strong>数据站</strong><span>DATA</span></div>
        <div class="embedded-header-actions"><span :class="['source-indicator',{demo:source==='demo'}]"><i/>{{source==='demo'?'示例数据':'公开数据'}}</span><a :href="'/data-lab.html?layout=overview&view='+view+'&source='+source+'&rule='+rule" target="_blank" rel="noopener" class="embedded-open-link">完整窗口 <Icon name="external" :size="14"/></a><button v-if="!embedOnly" class="icon-button" :aria-label="windowExpanded?'还原内嵌窗口':'展开内嵌窗口'" :title="windowExpanded?'还原窗口':'展开窗口'" @click="windowExpanded=!windowExpanded"><Icon :name="windowExpanded?'collapse':'expand'" :size="17"/></button></div>
      </header>
      <header v-else class="station-header"><a class="station-brand" href="/" aria-label="返回 Salasasa 主站"><span class="brand-symbol"><i/><i/><i/></span><span>SALASASA<small>DATA STATION</small></span></a><div class="header-title"><span class="header-slash">/</span>数据站<span class="header-meta">公开统计与牌谱资料</span></div><div class="header-right"><span :class="['source-indicator',{demo:source==='demo'}]"><i/>{{source==='demo'?'示例数据':'公开数据'}}</span><a href="/" class="back-link">返回主站 <Icon name="external" :size="14"/></a></div></header>
      <nav class="primary-nav" aria-label="数据站导航"><span class="nav-caption">DATA INDEX</span><button v-for="(item,i) in views" :key="item.key" :class="{active:view===item.key}" :aria-current="view===item.key?'page':undefined" @click="navigate(item.key)"><Icon :name="item.icon" :size="19"/><span>{{item.name}}</span><small>0{{i+1}}</small></button><div class="nav-bottom"><span class="nav-mark">s.</span><p>平台 / 玩家 / 对局<br>公开数据档案</p><span>PUBLIC DATA ARCHIVE</span></div></nav>
      <div class="stage">
        <div v-if="layout==='embedded'" class="embedded-range-bar">
          <div class="embedded-range-summary"><span>{{view==='duplicate'?'已公开牌山':ruleName}}</span><template v-if="['overview','records','fans'].includes(view)"><i/><strong>{{scopeCaption}}</strong></template><template v-if="view==='overview'"><i/><span>趋势 {{days}} 天</span></template></div>
          <div class="embedded-range-actions"><span class="embedded-asof" v-if="view==='overview'">累计截至 {{dataset.meta.as_of_date||'—'}}</span><button v-if="view!=='duplicate'" :aria-expanded="filtersOpen" aria-controls="station-filters" :class="{active:filtersOpen}" @click="filtersOpen=!filtersOpen"><Icon name="filter" :size="15"/>{{filtersOpen?'收起筛选':'筛选'}}<Icon name="chevron" :size="13" class="filter-chevron"/></button><button v-if="view==='overview'" class="icon-button" aria-label="刷新内嵌数据" title="刷新数据" @click="refresh"><Icon name="refresh" :size="16"/></button></div>
        </div>
        <aside id="station-filters" class="filter-dock" v-if="view!=='duplicate'" v-show="layout!=='embedded'||filtersOpen" aria-label="数据范围"><div class="filter-title"><Icon name="filter" :size="17"/><strong>数据范围</strong><span>{{source==='demo'?'示例':'公开'}}</span></div><label class="rule-field"><span>规则</span><select v-model="rule" aria-label="统计规则"><option v-for="r in rules" :key="r.key" :value="r.key">{{r.stats_name}}</option></select></label><template v-if="['overview','records','fans'].includes(view)"><div class="tier-field"><span class="field-label">场次</span><div class="tier-options"><button :class="{active:tier==='total'&&!eventId}" @click="selectTier('total')">全部</button><button v-for="r in rows.filter(row=>!row.label)" :key="r.match_tier" :class="{active:tier===r.match_tier&&!eventId}" @click="selectTier(r.match_tier)">{{tierLabel(r.match_tier)}}</button></div></div><label class="event-field"><span>比赛 / 基地</span><select v-model="eventId" aria-label="比赛或基地"><option value="">常规场次</option><option v-for="event in dataset.events" :key="event.event_id||event.id" :value="event.event_id||event.id">{{event.name||event.event_name||event.event_id}}</option></select></label></template><label class="range-field" v-if="view==='overview'"><span>趋势区间</span><select v-model.number="days" aria-label="趋势区间"><option :value="7">最近 7 天</option><option :value="30">最近 30 天</option><option :value="90">最近 90 天</option></select></label><div class="filter-help"><Icon name="info" :size="15"/><p>{{view==='players'?'在查询表单中选择对局类型和日期。':view==='analysis'?'资料索引按规则归类，口径与累计汇总独立。':'累计数据截至统计日；区间只控制趋势。'}}</p></div><div v-if="view!=='players'" class="filter-stamp"><span>STATISTICS THROUGH</span><strong>{{dataset.meta.as_of_date||'—'}}</strong><small>北京时间 · 04:00 切分</small></div></aside>
        <main ref="mainContent" class="page-body" id="main-content" :tabindex="layout==='embedded'?0:undefined">
          <div v-if="source==='demo'" class="demo-notice"><strong>虚构示例数据</strong><span>用于比较布局和交互，不代表真实玩家或平台表现。</span></div>
          <header class="page-heading"><div><span class="eyebrow">{{currentView.en}}</span><h1>{{currentView.name}}<span v-if="view==='overview'" class="heading-rule">{{ruleName}}</span></h1><p>{{currentView.description}}</p></div><div class="page-actions"><span v-if="['overview','fans','records'].includes(view)" class="scope-chip">{{scopeCaption}}</span><button v-if="view==='overview'" class="icon-button" aria-label="刷新平台数据" title="刷新数据" @click="refresh"><Icon name="refresh" :size="18"/></button></div></header>
          <section v-if="displayState==='loading'" class="state-card skeleton-page" aria-live="polite" aria-busy="true"><div class="skeleton-metrics"><i/><i/><i/><i/></div><div class="skeleton-chart"/><p>{{previewState==='loading'?'加载状态预览':'正在载入公开统计…'}}</p><button v-if="previewState!=='normal'" class="secondary-button" @click="previewState='normal'">返回正常状态</button></section>
          <section v-else-if="displayState==='error'" class="state-card error-state" role="alert"><Icon name="info" :size="40"/><h2>暂时无法读取数据</h2><p>{{previewState==='error'?'这是失败状态预览，页面不会把未取得的数据当作零。':error}}</p><button class="primary-button" @click="previewState==='error'?previewState='normal':loadStats()">重新载入</button></section>
          <section v-else-if="displayState==='empty'" class="state-card empty-state"><Icon name="record" :size="44"/><h2>这个范围还没有数据</h2><p>保留当前筛选，你可以选择其他场次，或等待新的对局完成。</p><button class="primary-button" @click="previewState==='empty'?previewState='normal':(rule='guobiao',selectTier('total'))">{{previewState==='empty'?'返回正常状态':'返回国标总览'}}</button></section>
          <template v-else-if="view==='overview'">
            <template v-if="layout==='overview'"><MetricStrip :metrics="metrics"/><div class="dashboard-top"><TrendChart :series="series" @select-day="selectedDay=$event"/><ScopeMatrix :player-count="definition?.player_count||4" :rows="rows" :selected="tier" @select="selectTier"/></div><div class="dashboard-bottom"><FanView :fans="fans" :supported="fanSupported" compact/><RecordTable :records="records" :total="recordTotal" :loading="recordLoading" :error="recordError" compact @select="chooseRecord" @retry="loadRecords"/></div><div class="overview-bottom-link"><span>继续查看个人表现或完整对局资料</span><button class="text-button" @click="navigate('players')">查询玩家 <Icon name="arrow" :size="16"/></button><button class="text-button" @click="navigate('records')">全部牌谱 <Icon name="arrow" :size="16"/></button></div></template>
            <template v-else-if="layout==='workbench'"><div class="workbench-status"><span><i/>当前范围 / {{ruleName}} / {{scopeCaption}}</span><span>累计统计 {{dataset.meta.as_of_date}}</span></div><MetricStrip :metrics="metrics"/><ScopeMatrix :player-count="definition?.player_count||4" :rows="rows" :selected="tier" :unit="unit" dense @select="selectTier"/><div class="workbench-charts"><TrendChart :series="series" initial="bar" compact @select-day="selectedDay=$event"/><FanView :fans="fans" :supported="fanSupported" compact initial="table"/></div><RecordTable :records="records" :total="recordTotal" :page="recordPage" :loading="recordLoading" :error="recordError" @page="recordPage=$event" @select="chooseRecord" @retry="loadRecords"/></template>
            <template v-else-if="layout==='report'"><section class="report-lead"><div class="report-number"><span>截至 {{dataset.meta.as_of_date}} 的累计记录</span><strong>{{count(total?.total_games)}}<small>场</small></strong><h2>累计表现<br>与近期对局趋势</h2></div><div class="report-abstract"><span class="report-kicker">本期观察 / {{scopeCaption}}</span><p>在 {{ruleName}} 的当前场次范围中，已记录 <b>{{count(total?.total_rounds)}}</b> 个小局。最近 {{days}} 天共有 <b>{{count(periodGames)}}</b> 场对局。</p><dl><div><dt>自摸占和牌</dt><dd>{{percent(total?.self_draw_count,total?.win_count)}}</dd></div><div><dt>平均和牌值</dt><dd>{{metrics[3].value}} <small>{{unit}}</small></dd></div></dl><span class="subtle">累计数据与区间趋势分别呈现。</span></div></section><section class="report-chapter"><div class="chapter-caption"><span>01</span><h2>对局的节奏</h2><p>{{peak.date}} 是当前区间内对局最多的一天，共 {{count(peak.value)}} 场。切换图表，观察每天的变化。</p></div><TrendChart :series="series" @select-day="selectedDay=$event"/></section><section class="report-chapter"><div class="chapter-caption"><span>02</span><h2>样本的轮廓</h2><p>按场次拆分累计样本，查看当前范围内各番种的出现频次。</p></div><div class="report-pair"><ScopeMatrix :player-count="definition?.player_count||4" :rows="rows" :selected="tier" @select="selectTier"/><FanView :fans="fans" :supported="fanSupported" compact/></div></section><section class="report-chapter"><div class="chapter-caption"><span>03</span><h2>回到对局</h2><p>从一行记录进入牌谱，查看数据背后的实际过程。</p><button class="text-button" @click="navigate('records')">打开全部记录 <Icon name="arrow" :size="16"/></button></div><RecordTable :records="records" :total="recordTotal" :loading="recordLoading" :error="recordError" compact @select="chooseRecord" @retry="loadRecords"/></section></template>
            <template v-else-if="layout==='explorer'"><div class="explorer-summary"><div><span>当前累计样本</span><strong>{{count(total?.total_games)}}<small>场</small></strong></div><div><span>最近 {{days}} 天</span><strong>{{count(periodGames)}}<small>场</small></strong></div><div class="explorer-instruction"><Icon name="search" :size="24"/><p>查看每日分布<br>打开牌谱详情</p></div></div><TrendChart :series="series" initial="heat" compact @select-day="selectedDay=$event"/><RecordTable :records="records.slice(0,4)" :total="recordTotal" :selected-id="contextRecord?.game_id" :loading="recordLoading" :error="recordError" :pagination="false" cards compact @select="chooseRecord" @retry="loadRecords"/><button class="explorer-more" @click="navigate('records')">进入完整牌谱库 <Icon name="arrow" :size="17"/></button></template>
            <template v-else-if="layout==='embedded'">
              <div class="embedded-overview">
                <MetricStrip :metrics="metrics"/>
                <div class="embedded-chart-row"><TrendChart :series="series" compact @select-day="selectedDay=$event"/><ScopeMatrix :player-count="definition?.player_count||4" :rows="rows" :selected="tier" @select="selectTier"/></div>
                <div class="embedded-record-row"><div class="embedded-records"><RecordTable :records="records.slice(0,3)" :total="recordTotal" :loading="recordLoading" :error="recordError" compact @select="chooseRecord" @retry="loadRecords"/><button class="embedded-records-more" @click="navigate('records')">查看全部牌谱 <Icon name="arrow" :size="15"/></button></div><FanView :fans="fans" :supported="fanSupported" compact/></div>
              </div>
            </template>
          </template>
          <PlayerView v-else-if="view==='players'" :rule="rule" :source="source" :initial-query="playerQuery" @select-record="detail=$event"/>
          <template v-else-if="view==='records'"><div v-if="visibleClassics.length" class="classics-section"><div class="section-caption"><h2>精选回看</h2><span>人工收录的公开片段</span></div><div class="classic-cards"><button v-for="(record,i) in visibleClassics.slice(0,3)" :key="record.id||record.game_id" @click="detail={...record,players:record.players||[]}"><span class="classic-number">0{{i+1}}</span><div><span class="eyebrow">SELECTED RECORD</span><h3>{{record.description||record.game_id}}</h3><p>第 {{record.round||'—'}} 局 <span>·</span> {{dateLabel(record.created_at_game||record.created_at)}}</p></div><Icon name="arrow" :size="21"/></button></div></div><p v-if="extrasError" class="notice">精选资料：{{extrasError}}</p><RecordTable :records="records" :total="recordTotal" :page="recordPage" :loading="recordLoading" :error="recordError" :cards="layout==='explorer'" @page="recordPage=$event" @select="detail=$event" @retry="loadRecords"/></template>
          <template v-else-if="view==='fans'"><div class="fan-summary"><div><span>已记录番种</span><strong>{{fans.filter(f=>f.value>0).length}}<small>种</small></strong></div><p>以当前范围的和牌次数作为分母。<br>同一次和牌可以包含多个番种，花牌等可重复计数，频次之和不等于和牌总数。</p><span class="scope-chip">{{count(total?.win_count)}} 次和牌</span></div><FanView :fans="fans" :supported="fanSupported" :initial="layout==='explorer'?'matrix':layout==='workbench'?'table':'bars'"/></template>
          <AnalysisView v-else-if="view==='analysis'" :hierarchy="hierarchy" :rule="rule" :error="extrasError"/>
          <DuplicateView v-else-if="view==='duplicate'" :source="source" @select-record="detail=$event"/>
          <footer class="content-footer"><span>Salasasa · 数据站</span><span>{{source==='demo'?'虚构示例 / 仅用于设计比较':'平台聚合 / 截至 '+(dataset.meta.as_of_date||'—')}}</span><button class="text-button" @click="notes.showModal()">口径与方案说明</button></footer>
        </main>
        <aside v-if="layout==='explorer'&&view==='overview'&&displayState==='normal'" class="context-panel"><div class="context-heading"><span>CONTEXT</span><h2>{{contextRecord?'对局上下文':'当前观察'}}</h2></div><template v-if="contextRecord"><div class="context-record-id mono">{{contextRecord.game_id}}</div><p class="subtle">{{dateLabel(contextRecord.created_at)}} · {{sceneName(contextRecord)}}</p><div class="context-players"><div v-for="p in contextRecord.players" :key="p.user_id"><span>{{p.username}}</span><strong :class="{'score-positive':p.score>0}">{{signed(p.score)}}</strong></div></div><button class="primary-button" @click="detail=contextRecord">完整详情 <Icon name="arrow" :size="16"/></button><button class="text-button context-reset" @click="contextRecord=null">返回范围概览</button></template><template v-else><div class="context-scope"><span>{{ruleName}}</span><strong>{{scopeCaption}}</strong><p>累计小局 <b>{{count(total?.total_rounds)}}</b></p></div><dl class="context-stats"><div><dt>自摸占和牌</dt><dd>{{percent(total?.self_draw_count,total?.win_count)}}</dd></div><div><dt>平均和牌值</dt><dd>{{metrics[3].value}}<small>{{unit}}</small></dd></div><div><dt>平均和牌巡目</dt><dd>{{mean(total?.total_win_turn,total?.win_count,1)}}</dd></div></dl><div v-if="selectedDay" class="selected-day"><span>已选统计日</span><strong>{{selectedDay.date}}</strong><p>{{count(selectedDay.value)}} 场对局</p><small>下方牌谱为最近记录，不作日期联动。</small></div><FanView :fans="fans" :supported="fanSupported" compact initial="matrix"/></template><div class="context-help"><Icon name="info" :size="16"/><p>左侧控制数据范围。选择牌谱后，这里显示该场对局摘要。</p></div></aside>
      </div>
    </div>
    <RecordDetail v-if="detail" :key="detail.game_id" :record="detail" :source="source" @close="detail=null" @player="choosePlayer"/>
    <dialog ref="notes" class="notes-dialog"><div class="dialog-heading"><div><span class="eyebrow">DESIGN REVIEW</span><h2>五种布局，同一组数据。</h2></div><button autofocus class="icon-button" aria-label="关闭方案说明" @click="notes.close()"><Icon name="close"/></button></div><div class="dialog-body"><p class="notes-intro">当前方案：<strong>{{currentLayout.name}}</strong>。五套预览共用查询范围与数据来源，切换布局不会把统计替换为另一组数字。</p><div class="layout-comparison"><button v-for="(item,i) in layouts" :key="item.key" :class="{active:layout===item.key}" @click="layout=item.key;notes.close()"><span>0{{i+1}}</span><h3>{{item.name}}</h3><strong>{{item.tag}}</strong><p>{{item.desc}}</p></button></div><div class="embed-delivery"><div><h3>内嵌版入口</h3><p>内容在窗口内部滚动，顶部标签始终保留。此入口不含设计切换栏，适合 WebView 或 iframe；当前尚未写入 Unity 场景。</p></div><a class="secondary-button" href="/data-lab.html?layout=embedded&embed=1&source=live" target="_blank" rel="noopener">打开纯内嵌页 <Icon name="external" :size="15"/></a></div><h3>现有数据站怎样重组</h3><div class="table-scroll"><table><thead><tr><th>现有入口</th><th>本次归并</th><th>保留的能力</th></tr></thead><tbody><tr><td>玩家数据</td><td>玩家档案</td><td>公开查询、基础统计、个人顺位、最近牌谱</td></tr><tr><td>平台数据</td><td>平台总览 / 番种观察</td><td>累计指标、每日趋势、场次分布、番种频次</td></tr><tr><td>其他数据</td><td>对局与精选</td><td>保留人工收录牌谱，去掉周榜及涨跌榜</td></tr><tr><td>牌谱分析</td><td>深度分析</td><td>资料覆盖 + 原有登录、缓存、完整牌谱分析入口</td></tr><tr><td>复式密钥查询</td><td>复式资料</td><td>已解锁牌山、公开时间、关联对局</td></tr></tbody></table></div><h3>数据来源与边界</h3><ul class="notes-list"><li><b>本地接口数据</b>来自当前开发服务的公开查询；无榜单模块，无跨玩家成绩排序。</li><li><b>累计 / 区间</b>：平台累计值与番种截至统计日；7 / 30 / 90 天只影响趋势。最近牌谱按时间分页。</li><li><b>个人顺位</b>是玩家自己的结算分布，可用于复盘，不是排行榜。</li><li><b>完整牌谱</b>继续使用已有登录与下载配额；本预览只导出可见摘要。</li><li><b>尚无接口</b>的留存、活跃人数、听牌效率等不展示虚构结论。缺少明细显示「—」。</li><li><b>状态预览</b>可在顶栏切换空数据、加载中和失败；示例数据始终有标记。</li></ul><details class="api-mapping"><summary>查看字段与接口映射</summary><dl><div><dt>总览 / 番种 / 每日趋势</dt><dd><code>GET /api/platform/stats</code><p>totals · fans · daily · meta.as_of_date / date_from / date_to</p></dd></div><div><dt>最近牌谱 / 精选</dt><dd><code>GET /api/platform/recent-records</code><br><code>GET /api/platform/fun-stats</code><p>仅读取精选 classics，不展示 gainers / losers。</p></dd></div><div><dt>玩家档案</dt><dd><code>GET /api/player/info/:id</code><br><code>GET /api/player/rank-stats/:id</code><br><code>GET /api/player/records/:id</code></dd></div><div><dt>资料覆盖 / 复式</dt><dd><code>GET /api/platform/home-stats</code><br><code>GET /api/duplicate-walls/public</code><br><code>GET /api/duplicate-walls/public/:key</code></dd></div></dl></details></div></dialog>
  </div>
</template>
